import {equipmentDetails} from './equipment.js';
import {ROOM_TYPES,OBJECTS,area,levelOf,objectLevel,openingLevel,openingParent} from './engine.js';
import {icon,thumb,esc,fmt,euro} from './assets.js';

import {surfaceFields,surfaceThumb} from './surface-ui.js';
export const mobileQuery='(max-width: 760px), (max-height: 520px) and (pointer: coarse)';
export function sheetHeader(title,subtitle='',back=''){return `<div class="m-sheet-header">${back?`<button class="m-back" data-mobile="${back}" aria-label="Retour">${icon('arrow')}</button>`:''}<div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-btn m-expand" data-mobile="expand" aria-label="Agrandir ou réduire le panneau">${icon('expand')}</button><button class="icon-btn m-close" data-close-drawer aria-label="Revenir au plan">${icon('close')}</button></div>`;}
export function addTabs(tab){return `<div class="m-add-tabs" role="group" aria-label="Que voulez-vous ajouter ?">${[['rooms','room','Pièces'],['surfaces','layers','Surfaces'],['furniture','sofa','Mobilier'],['openings','window','Ouvertures'],['ceiling','layers','Plafonds'],['pool','bath','Piscine']].map(([k,i,t])=>`<button data-mobile-add="${k}" class="${tab===k?'active':''}">${icon(i)}${t}</button>`).join('')}</div>`;}
export function projectHub(s,C){return sheetHeader('Mon projet',s.name)+`<div class="m-project-intro"><span>Votre lieu, en un coup d’œil</span><div><strong>${fmt(C.home)} <small>m² pour vivre</small></strong><strong>${fmt(C.free)} <small>m² libres au sol</small></strong></div></div><div class="m-menu-list">${[['building','building','Le bâtiment',`${fmt(s.building.w)} × ${fmt(s.building.l)} m · ${fmt(s.building.h)} m de haut`],['levels','layers','Étages & mezzanines',`${s.levels.length} niveau${s.levels.length>1?'x':''} · planchers et escaliers`],['technical','lightbulb','Plan technique','Électricité, eau et tableau'],['comfort','sun','Isolation & lumière','Ajuster le confort de votre lieu'],['budget','wallet','Mon budget',`${euro(C.budget)} estimés · hypothèses modifiables`]].map(([key,i,t,d])=>`<button data-mobile="${key}"><span class="m-menu-icon">${icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</div><button class="btn full m-report-button" data-mobile="report">${icon('eye')}Voir le bilan complet</button><div class="m-project-links"><button data-action="projects">${icon('folder')}Mes plans</button><button data-mobile="menu">${icon('export')}Exporter</button></div>`;}
export function levelPicker(s,C,active){return `<p class="m-dialog-intro">Choisissez le niveau à afficher et à aménager.</p><div class="m-level-list">${s.levels.map(l=>{const row=C.levels.find(x=>x.id===l.id);return `<button class="${active===l.id?'active':''}" data-mobile-level="${l.id}"><span class="m-menu-icon">${icon(l.kind==='ground'?'building':'layers')}</span><span><strong>${esc(l.name)}</strong><small>+${fmt(l.elevation)} m · ${fmt(row.home)} m² de pièces${l.kind!=='ground'?` · ${fmt(row.deckArea)} m² de plancher`:''}</small></span>${active===l.id?icon('check'):icon('chevron')}</button>`;}).join('')}</div><div class="m-dialog-actions"><button class="btn primary full" data-action="add-level">${icon('plus')}Ajouter un étage ou une mezzanine</button><button class="btn full" data-mobile="level-settings">${icon('ruler')}Régler le niveau affiché</button></div>`;}
export function moreMenu(){return `<div class="m-menu-list"><button data-action="projects"><span class="m-menu-icon">${icon('folder')}</span><span><strong>Mes plans</strong><small>Ouvrir, créer ou retrouver une version</small></span></button><button data-action="versions"><span class="m-menu-icon">${icon('layers')}</span><span><strong>Versions du plan</strong><small>Enregistrer ou restaurer</small></span></button><button data-mobile="rename"><span class="m-menu-icon">${icon('file')}</span><span><strong>Renommer le projet</strong></span></button><button data-export="archive"><span class="m-menu-icon">${icon('file')}</span><span><strong>Sauvegarder le projet</strong><small>Fichier JSON avec les versions</small></span></button><button data-export="png"><span class="m-menu-icon">${icon('eye')}</span><span><strong>Exporter la vue en image</strong><small>PNG · vue affichée</small></span></button><button data-export="svg"><span class="m-menu-icon">${icon('plan')}</span><span><strong>Exporter le plan vectoriel</strong><small>SVG · niveau affiché</small></span></button><button data-action="import"><span class="m-menu-icon">${icon('folder')}</span><span><strong>Importer un projet</strong><small>Reprendre un fichier JSON</small></span></button><button data-mobile="help"><span class="m-menu-icon">${icon('help')}</span><span><strong>Prendre en main le studio</strong><small>Les gestes et les calculs</small></span></button></div>`;}
export function selectionCard(name,type,areaValue,moving=false,{step=.1,axis='both',resize=false}={}){
 const distance=step<1?`${fmt(step*100)} cm`:`${fmt(step)} m`;
 return `<div class="m-selection-title"><div><span>${moving?'PLACEMENT':type==='room'?'PIÈCE':type==='opening'?'OUVERTURE':type==='platform'?'PLANCHER':type==='surface'?'SURFACE':'ÉLÉMENT'}</span><strong>${esc(name)}${Number.isFinite(areaValue)?`<small>${fmt(areaValue)} m²</small>`:''}</strong></div><button class="icon-btn m-focus" data-mobile="focus" aria-label="Centrer cet élément sur le plan">${icon('fit')}</button>${moving?`<button class="m-move-done" data-mobile="cancel-mode">${icon('check')}Terminer</button>`:`<button class="icon-btn" data-mobile="deselect" aria-label="Désélectionner">${icon('close')}</button>`}</div>${!moving?`<div class="m-selection-actions"><button data-mobile="dimensions">${icon('ruler')}Dimensions</button><button data-mobile="move">${icon('hand')}Déplacer</button><button data-mobile="element-more">${icon('more')}Plus</button></div>`:''}${moving&&!resize?`<div class="m-nudge" role="group" aria-label="Déplacement précis"><button class="m-nudge-step" data-mobile="nudge-step" aria-label="Changer le pas de déplacement, actuellement ${distance}"><small>Pas de</small><strong>${distance}</strong></button>${[['left','la gauche',180,'x'],['up','le haut',-90,'y'],['down','le bas',90,'y'],['right','la droite',0,'x']].map(([key,label,rotation,dir])=>`<button data-mobile-nudge="${key}" aria-label="Déplacer de ${distance} vers ${label}" ${axis!=='both'&&axis!==dir?'disabled':''}><span style="--turn:${rotation}deg">${icon('arrow')}</span></button>`).join('')}</div>`:''}`;
}

export function elementBrowser(s,u){
 return sheetHeader('Dans mon plan',levelOf(s,u.levelId).name)+`<button class="m-level-shortcut" data-mobile="levels">${icon('layers')}Changer de niveau${icon('chevron')}</button><div class="m-add-tabs m-browse-tabs" role="group" aria-label="Éléments du niveau">${[['rooms','Pièces'],['surfaces','Surfaces'],['objects','Mobilier'],['openings','Ouvertures']].map(([key,title])=>`<button data-mobile-browse="${key}" class="${u.mobileBrowse===key?'active':''}">${title}</button>`).join('')}</div><label class="search">${icon('search')}<input id="mobile-find" placeholder="Retrouver un élément…" aria-label="Rechercher dans mon plan" value="${esc(u.mobileFind||'')}"></label><p class="m-browser-help">Touchez un élément pour le retrouver sur le plan.</p><div id="mobile-element-items">${elementItems(s,u)}</div>`;
}
export function elementItems(s,u){
 const query=(u.mobileFind||'').toLocaleLowerCase('fr'),tab=u.mobileBrowse||'rooms';
 const list=tab==='rooms'?s.rooms.filter(r=>r.levelId===u.levelId).map(r=>({type:'room',id:r.id,name:r.name,kind:r.type,detail:`${fmt(r.w)} × ${fmt(r.l)} m`,value:`${fmt(area(r))} m²`,room:true})):
 tab==='surfaces'?[...(s.surfaces||[]).filter(o=>o.levelId===u.levelId).map(o=>({type:'surface',id:o.id,name:o.name,kind:o.kind,detail:o.kind==='terrace'?'Terrasse ouverte':'Plancher de mezzanine',value:`${fmt(area(o))} m²`})),...(levelOf(s,u.levelId).platform?[{type:'platform',id:u.levelId,name:'Plancher ouvert',kind:'mezzanine',detail:'Plancher du niveau',value:`${fmt(area(levelOf(s,u.levelId).platform))} m²`}]:[])]:
 tab==='objects'?s.objects.filter(o=>objectLevel(s,o)===u.levelId||o.kind==='stairs'&&o.targetLevelId===u.levelId).map(o=>({type:'object',id:o.id,name:OBJECTS[o.kind].name,kind:o.kind,detail:o.kind==='stairs'?`Vers ${levelOf(s,o.targetLevelId).name}`:s.rooms.find(r=>r.id===o.roomId)?.name||'Libre dans le bâtiment',value:`${fmt(o.w,2)} × ${fmt(o.l,2)} m`})):
 s.openings.filter(o=>openingLevel(s,o)===u.levelId).map(o=>({type:'opening',id:o.id,name:({window:'Fenêtre',door:'Porte',bay:'Porte d’atelier'})[o.kind],kind:o.kind==='window'?'window':'door',detail:o.host==='room'?s.rooms.find(r=>r.id===o.roomId)?.name||'Mur de pièce':'Façade du bâtiment',value:`${fmt(o.w)} × ${fmt(o.h)} m`}));
 const items=list.filter(o=>`${o.name} ${o.detail}`.toLocaleLowerCase('fr').includes(query));
 if(!items.length)return `<div class="m-browser-empty">${icon(query?'search':tab==='rooms'?'room':tab==='objects'?'sofa':'window')}<strong>${query?'Aucun élément trouvé':tab==='rooms'?'Votre niveau est prêt à être aménagé':'Aucun élément pour le moment'}</strong><p>${query?'Essayez un autre nom.':'Ajoutez les éléments où vous voulez dans ce niveau.'}</p>${!query?`<button class="btn primary" data-mobile-add="${tab==='objects'?'furniture':tab}">${icon('plus')}${tab==='rooms'?'Créer une pièce':tab==='surfaces'?'Ajouter une surface':tab==='objects'?'Ajouter du mobilier':'Ajouter une ouverture'}</button>`:''}</div>`;
 return `<div class="m-element-count">${items.length} ${tab==='rooms'?(items.length>1?'pièces':'pièce'):tab==='surfaces'?(items.length>1?'surfaces':'surface'):tab==='openings'?(items.length>1?'ouvertures':'ouverture'):(items.length>1?'éléments':'élément')}</div><div class="m-element-list">${items.map(o=>`<button data-mobile-pick="${o.type}:${o.id}"><span class="m-element-thumb">${['surface','platform'].includes(o.type)?surfaceThumb(o.kind):o.type==='opening'?icon(o.kind):thumb(o.kind,o.room||false)}</span><span class="m-element-info"><strong>${esc(o.name)}</strong><small>${esc(o.detail)}</small><b>${o.value}</b></span>${icon('arrow')}</button>`).join('')}</div>`;
}
export function inspectorMarkup({s,u,C,o,type,name,field,select,line}){
 if(!o)return '';
 const tab=u.mobileEditTab||'dimensions',levelOptions=s.levels.map(l=>[l.id,l.name]),f=(label,key,unit='',step='.1',min=0,max='',val=o[key])=>field(label,'@'+key,unit,step,min,max,val);
 let basic='',position='',details='';
 if(type==='surface'){({basic,position,details}=surfaceFields({s,o,field,select}));}
 else if(type==='room'){
  basic=`<label class="field m-name-field"><span>Nom de la pièce</span><input data-entity-field="name" value="${esc(o.name)}" maxlength="50"></label><div class="fields">${f('Largeur','w','m','.1',.6,s.building.w)}${f('Longueur','l','m','.1',.6,s.building.l)}</div><div class="fields one">${f('Sous plafond','h','m','.1',1,15)}${select('Sur quel niveau ?','@levelId',levelOptions,o.levelId)}</div>`;
  position=`<p class="m-help-text">Déplacez la pièce au doigt ou ajustez sa position depuis l’angle du bâtiment.</p><button class="btn full" data-mobile="move">${icon('hand')}Déplacer sur le plan</button><div class="fields m-position-fields">${f('Depuis la gauche','x','m','.1',0,s.building.w-o.w)}${f('Depuis le haut','y','m','.1',0,s.building.l-o.l)}</div>`;
  const r=C.roomRows.find(r=>r.id===o.id);details=`<div class="fields one">${select('Usage de la pièce','@type',Object.entries(ROOM_TYPES).map(([k,v])=>[k,v.name]),o.type)}${f('Éclairage visé','lux','lux',50,50,2000)}</div><div class="m-readout">${line('Surface',`${fmt(r.area)} m²`)}${line('Luminaires estimés',String(r.fixtures))}${line('Vitrage extérieur',`${fmt(r.glass,2)} m²`)}</div>`;
 }else if(type==='object'){
  const parent=s.rooms.find(r=>r.id===o.roomId)||s.building;
  basic=`<div class="fields">${f('Largeur','w','m','.05',.15,parent.w)}${f('Profondeur','l','m','.05',.15,parent.l)}</div><div class="fields one">${select(o.kind==='stairs'?'Niveau de départ':'Sur quel niveau ?','@levelId',levelOptions,objectLevel(s,o))}${o.kind==='stairs'?select('Niveau d’arrivée','@targetLevelId',[["","Choisir un étage"],...s.levels.filter(l=>l.elevation>levelOf(s,objectLevel(s,o)).elevation).map(l=>[l.id,l.name])],o.targetLevelId||''):''}</div>`;
  position=`<button class="btn full" data-mobile="move">${icon('hand')}Déplacer sur le plan</button><div class="fields m-position-fields">${f('Position X','x','m','.05',0,parent.w-o.w)}${f('Position Y','y','m','.05',0,parent.l-o.l)}</div>${o.kind!=='stairs'?`<div class="fields one">${select('Dans quelle pièce ?','@roomId',[["","Libre dans le bâtiment"],...s.rooms.filter(r=>r.levelId===objectLevel(s,o)).map(r=>[r.id,r.name])],o.roomId||'')}</div>`:''}`;
  details=equipmentDetails(s,o,field,line)+`<div class="fields one">${f('Coût de cet élément','price','€',10,0,1e6,o.price??OBJECTS[o.kind].price)}</div>`;
 }else if(type==='opening'){
  const p=openingParent(s,o),owner=o.host==='room'?'room:'+o.roomId:o.host;
  basic=`<div class="fields">${f('Largeur','w','m','.1',.3,['north','south'].includes(o.wall)?p.w||s.building.w:p.l||s.building.l)}${f('Hauteur','h','m','.1',.3,15)}</div><div class="fields one">${f('Hauteur au-dessus du sol','sill','m','.1',0,15)}${select('Sur quel niveau ?','@levelId',levelOptions,openingLevel(s,o))}</div>`;
  position=`<div class="fields one">${select('Mur','@owner',[['building','Façade du bâtiment'],...s.rooms.filter(r=>r.levelId===openingLevel(s,o)).map(r=>['room:'+r.id,r.name]),...(o.host==='free'?[['free','Mur libre conservé']]:[])],owner)}${select('Côté du plan','@wall',[['north','En haut'],['east','À droite'],['south','En bas'],['west','À gauche']],o.wall)}${f('Distance depuis l’angle','offset','m','.1',0,100)}</div>`;
  details='<p class="m-help-text">Une fenêtre compte dans la lumière naturelle si elle donne réellement sur une façade de la pièce, au même niveau.</p>';
 }else{
  basic=`<div class="fields">${f('Largeur','w','m','.1',.6,s.building.w)}${f('Longueur','l','m','.1',.6,s.building.l)}</div><button class="btn full" data-mobile="level-settings">${icon('layers')}Altitude du plancher</button>`;
  position=`<button class="btn full" data-mobile="move">${icon('hand')}Déplacer sur le plan</button><div class="fields m-position-fields">${f('Position X','x','m','.1',0,s.building.w-o.w)}${f('Position Y','y','m','.1',0,s.building.l-o.l)}</div>`;
  details='<p class="m-help-text">Ce plancher ouvert complète celui des pièces. Il ne limite pas leur position.</p>';
 }
 return sheetHeader(name,type==='opening'?'Ouverture du niveau affiché':`${fmt(type==='room'?C.roomRows.find(r=>r.id===o.id).area:area(o))} m² · réglages de l’élément`)+`<div class="m-edit-tabs" role="group" aria-label="Réglages de l’élément">${[['dimensions','Dimensions'],['position','Position'],['details','Détails']].map(([k,t])=>`<button data-mobile-tab="${k}" class="${tab===k?'active':''}">${t}</button>`).join('')}</div><div data-mobile-panel="dimensions" ${tab!=='dimensions'?'hidden':''}>${basic}</div><div data-mobile-panel="position" ${tab!=='position'?'hidden':''}>${position}</div><div data-mobile-panel="details" ${tab!=='details'?'hidden':''}>${details}<div class="m-element-actions">${type!=='platform'?'<button class="btn" data-action="duplicate">'+icon('copy')+'Dupliquer</button><button class="btn danger" data-action="delete">'+icon('trash')+'Retirer</button>':''}</div></div>`;
}
